def test_homework_returns_structured_playbook():
    """POST /api/builds/homework returns a structured Chinese playbook."""
    response = client.post("/api/builds/homework", json={"pob_code": VALID_POB_CODE})
    assert response.status_code == 200

    data = response.json()

    # Must have the five sections of a playbook
    assert "core_idea" in data, "Missing core_idea (build philosophy)"
    assert "core_items" in data, "Missing core_items"
    assert "budget_alternatives" in data, "Missing budget_alternatives"
    assert "talent_highlights" in data, "Missing talent_highlights"
    assert "strength_review" in data, "Missing strength_review"

    # Each section must be non-empty text
    for key in ["core_idea", "talent_highlights", "strength_review"]:
        assert len(data[key]) > 0, f"{key} is empty"


def test_homework_with_invalid_code_returns_400():
    """POST /api/builds/homework with garbage returns 400."""
    response = client.post("/api/builds/homework", json={"pob_code": "garbage"})
    assert response.status_code == 400
    assert "detail" in response.json()
